const norm=v=>String(v||'').trim().toLowerCase().replace(/\s+/g,' ');
const exact=new Map(data.records.map(r=>[norm(r.scientific),r]));const lookup=new Map();const ambiguous=new Set();for(const r of data.records)for(const v of [r.nameEt,...r.aliases]){const k=norm(v);if(!k||ambiguous.has(k))continue;if(lookup.has(k)&&lookup.get(k)!==r){lookup.delete(k);ambiguous.add(k);}else lookup.set(k,r);}
function find(name){return exact.get(norm(name))||lookup.get(norm(name))||null;}
function restriction(name){const n=norm(name);return data.restrictions.find(r=>[r.scientific,r.nameEt,...r.aliases].some(v=>{const key=norm(v);return n===key||(r.rank==='genus'&&n.startsWith(key+' '));}))||null;}
function names(){const result={};for(const r of data.records)result[norm(r.scientific)]=r.scientific;for(const [key,r] of lookup)result[key]=r.scientific;for(const r of data.restrictions)for(const v of [r.nameEt,...r.aliases])result[norm(v)]=r.scientific;return result;}
function suitable(r,query={}){if(!r||restriction(r.scientific))return false;return (!query.month||(query.floweringScope==='europe'?r.ecology.floweringEuropeMonths:r.ecology.floweringMonths)?.includes(Number(query.month)))&&(!query.light||r.ecology.light?.includes(query.light))&&(!query.visitor||r.ecology.flowerVisitors?.includes(query.visitor));}
function deepFreeze(x){if(x&&typeof x==='object'){Object.values(x).forEach(deepFreeze);Object.freeze(x);}return x;}
window.KITAPlantDB=Object.freeze({data:deepFreeze(data),find,restriction,names,suitable});
